#include <iostream>
#include <vector>
using namespace std;

int interpolation_search(const vector<int>& arr, int target) {
    int low = 0, high = arr.size() - 1;
    while (low <= high && target >= arr[low] && target <= arr[high]) {
        if (arr[low] == arr[high]) {
            if (arr[low] == target) return low;
            else break;
        }
        int pos = low + (int)((long long)(high - low) * (target - arr[low]) / (arr[high] - arr[low]));
        if (pos < low || pos > high) break;
        if (arr[pos] == target)
            return pos;
        if (arr[pos] < target)
            low = pos + 1;
        else
            high = pos - 1;
    }
    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, target;
    cin >> n >> target;
    vector<int> arr(n);
    for (int i = 0; i < n; ++i) cin >> arr[i];
    cout << interpolation_search(arr, target) << endl;
}

