#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<int> res;
    vector<int> freq(n + 2, 0);
    int cnt = 0, mex = 0, l = 0;

    for (int i = 0; i < n; ++i) {
        freq[a[i]]++;
        while (freq[mex]) ++mex;
        ++cnt;
        if (mex == cnt) {
            res.push_back(mex);
            for (int j = l; j <= i; ++j) freq[a[j]]--;
            l = i + 1;
            cnt = 0;
            mex = 0;
        }
    }

    cout << res.size() << endl;
    for (int x : res) cout << x << ' ';
    cout << endl;
}

#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<int> res;
    unordered_map<int, int> freq;
    int l = 0, r = 0;
    while (l < n) {
        freq.clear();
        int cnt = 0, mex = 0;
        // Find the MEX for the current window
        for (r = l; r < n; ++r) {
            if (a[r] < n) {
                if (freq[a[r]] == 0) cnt++;
                freq[a[r]]++;
            }
            // Try to update mex
            while (freq.count(mex)) ++mex;
            if (cnt == mex) {
                // Valid subarray found
                res.push_back(mex);
                ++r;
                break;
            }
        }
        l = r;
    }

    cout << res.size() << endl;
    for (int x : res) cout << x << ' ';
    cout << endl;
}

#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<int> res;
    unordered_set<int> seen;
    vector<int> freq(n + 2, 0);
    int unique = 0;
    int l = 0;

    for (int i = 0; i < n; ++i) {
        if (freq[a[i]] == 0) unique++;
        freq[a[i]]++;
        seen.insert(a[i]);
        // Find current MEX
        int mex = 0;
        while (seen.count(mex)) ++mex;
        if (unique == mex) {
            res.push_back(i - l + 1);
            // Reset for next subarray
            seen.clear();
            for (int j = l; j <= i; ++j) freq[a[j]] = 0;
            unique = 0;
            l = i + 1;
        }
    }

    cout << res.size() << endl;
    for (int x : res) cout << x << ' ';
    cout << endl;
}
